// Turn the downloaded prescription image into a Gemini request
const base = $('Normalize Message').first().json;
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
const mime = $input.first().binary?.data?.mimeType || base.mimeType || 'image/jpeg';

const prompt = 'You are a pharmacy assistant. Read this prescription image and extract every medicine. ' +
  'Return ONLY JSON in this format: {"medicines":[{"name":"","strength":"","quantity":1}]}. ' +
  'Use the English brand or generic name. If nothing is readable return {"medicines":[]}.';

return [{ json: {
  from: base.from,
  name: base.name,
  geminiBody: {
    contents: [{ parts: [
      { text: prompt },
      { inline_data: { mime_type: mime, data: buf.toString('base64') } }
    ]}],
    generationConfig: { responseMimeType: 'application/json' }
  }
}}];

// Fuzzy-match each name to the catalog, check stock, and decide what a pharmacist must see.
const req = $('AI Read Request').first().json; const src = ($('Prepare Prescription Read').isExecuted ? $('Prepare Prescription Read') : $('Prepare Text Read')).first().json;
let r; try { r = JSON.parse((req.candidates?.[0]?.content?.parts || []).map(p => p.text).join('')); } catch (e) { r = { readable: false, medicines: [] }; }
const cat = $input.all().map(i => i.json).filter(p => p.sku);
const norm = s => String(s || '').toLowerCase().replace(/[^a-z0-9\u0600-\u06FF]/g, '');
const lev = (a, b) => { const d = Array.from({ length: a.length + 1 }, (_, i) => [i]); for (let j = 1; j <= b.length; j++) d[0][j] = j;
  for (let i = 1; i <= a.length; i++) for (let j = 1; j <= b.length; j++) d[i][j] = Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1)); return d[a.length][b.length]; };
const lines = [], unclear = [];
for (const m of (r.medicines || []).slice(0, 10)) {
  const n = norm(m.name); if (!n || n === '?') { unclear.push(m.name || '?'); continue; }
  const best = cat.map(p => ({ p, d: lev(n, norm(p.name)) })).sort((a, b) => a.d - b.d)[0];
  if (!best || best.d > Math.max(2, Math.floor(n.length * 0.35))) { unclear.push(m.name); continue; }
  const p = best.p; const qty = Math.max(1, Math.min(9, Math.round(Number(m.qty) || 1)));
  const alts = cat.filter(x => x.sku !== p.sku && x.active_ingredient === p.active_ingredient && x.strength === p.strength && Number(x.stock) >= qty);
  lines.push({ sku: p.sku, name: p.name + ' ' + p.strength, qty, price: Number(p.price_egp), in_stock: Number(p.stock) >= qty, controlled: p.controlled === 'yes',
    fuzzy: best.d > 0, alternative: !(Number(p.stock) >= qty) && alts[0] ? alts[0].name + ' ' + alts[0].strength + ' (' + alts[0].sku + ', ' + alts[0].price_egp + ' EGP)' : '' });
}
const needsPharmacist = r.is_prescription || !r.readable || unclear.length > 0 || lines.some(l => l.controlled || !l.in_stock || l.fuzzy);
const group = 'R-' + $now.setZone('Africa/Cairo').toFormat('yyMMdd') + '-' + Math.random().toString(36).slice(2, 6).toUpperCase();
return [{ json: { ...src, b64: undefined, prompt: undefined, group, lines, unclear, readable: r.readable !== false, needsPharmacist,
  nothing: !lines.length && !unclear.length, total: lines.filter(l => l.in_stock).reduce((s, l) => s + l.qty * l.price, 0) } }];

