const m = $('Match Catalog').first().json;
const lines = m.lines || [];

const body = lines.map(l => {
  const notes = [
    l.fuzzy ? '(fuzzy match)' : '',
    l.alternative ? `\n   ↳ alternative: ${l.alternative}` : ''
  ].join('');
  return `• ${l.name} x${l.qty}${notes}`;
}).join('\n');

const unclear = (m.unclear && m.unclear.length)
  ? `\n\n❓ unclear: ${m.unclear.join(', ')}`
  : '';

const message = `Order from ${m.customer_name}\n\n${body}${unclear}`;

return [{ json: { ...$input.first().json, message } }];

// Only this request's lines, only while still pending. Approval re-checks stock at this moment.
const d = $('Parse Decision').first().json;
const lines = $('Get Reservations').all().map(i => i.json).filter(l => String(l.res_id).startsWith(d.group + '-'));
const stock = Object.fromEntries($input.all().map(i => [i.json.sku, Number(i.json.stock)]));
if (!lines.length) return [{ json: { ...d, ok: false, toast: 'Already decided or not found' } }];
if (d.action === 'approve') for (const l of lines) { stock[l.sku] -= Number(l.qty); if (stock[l.sku] < 0) return [{ json: { ...d, ok: false, toast: 'Not enough stock for ' + l.name + '. Edit the request or reject.' } }]; }
const exp = $now.setZone('Africa/Cairo').plus({ hours: 2 }).toFormat('yyyy-MM-dd HH:mm');
return [{ json: { ...d, ok: true, toast: d.action === 'approve' ? 'Approved' : 'Rejected', lines, newStock: [...new Set(lines.map(l => l.sku).filter(Boolean))].map(s => ({ sku: s, stock: stock[s] })), exp, wa_phone_id: lines[0].wa_phone_id, total: lines.reduce((s, l) => s + Number(l.total_egp), 0) } }];

